
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_r2scan0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_r2scan0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.689915865478427e+00, -3.615703463673078e+00, -3.511679211095034e+00, -3.367505714504570e+00, -3.170891828488589e+00, -2.908868541952156e+00, -2.570866156247852e+00, -2.154266755041466e+00, -1.671750837235621e+00, -1.151848467220482e+00, -6.681481260193713e-01, -5.105260198173436e-01, -5.104377767123188e-01, -4.228973178349150e-01, -2.909857164764012e-01, -1.621703088684628e-01, -6.633666880796478e-02, -1.844776581910538e-02, -2.698426254882342e-03, -1.307587839722489e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


